"""Produce immutable batch dossiers with complete bilingual decision texts."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def render(c,effects):
 d=ROOT/'documentos';by={r['id']:r for r in c['records']};by_source={e['source']:e for e in effects};batch=json.loads((d/'integracion_lote_02.json').read_text());selected=[by_source[rid] for rid in batch['ids']]
 for lang in ['es','pt']:
  es=lang=='es';path=d/f'integracion_normativa_lote_02_2026_{lang}.md'
  if path.exists():continue
  text=('# Integración normativa 2026 — segundo lote: veinte decisiones\n\n> Edición de trabajo no oficial. Avance al cierre de este lote: 30/398 decisiones examinadas por sus efectos; 368 pendientes. Traducción y cotejo textual del Digesto completos: 398/398. Este lote reúne diecinueve decisiones SC CCXLI–CCXXII (excluye SC CCXXXIX, ya examinada) y CE CII. Integración exhaustiva y revisión editorial final pendientes; sin certificación externa.\n\n' if es else '# Integração normativa 2026 — segundo lote: vinte decisões\n\n> Edição de trabalho não oficial. Avanço ao final deste lote: 30/398 decisões examinadas quanto aos efeitos; 368 pendentes. Tradução e cotejo textual do Digesto completos: 398/398. Lote reúne dezenove decisões SC CCXLI–CCXXII (exclui SC CCXXXIX, já examinada) e CE CII. Integração exaustiva e revisão editorial final pendentes; sem certificação externa.\n\n')
  text+=('## Resultado de la integración\n\n- Incorporada la nueva redacción del encabezamiento de Actas art. 3 aprobada en CE-CII. Conservados §§ 1–3, con anotación sobre los modelos históricos que todavía mencionan hojas numeradas. El art. 20 no se reemplaza.\n- Dieciséis decisiones de nombramientos/nominaciones registradas con listas completas; archivo FEP separado de una elección. No se insertan nombres personales en los artículos generales del Manual.\n- La identidad visual UCP y el Proyecto Alagoas se registran como políticas específicas, sin convertirlas en reformas constitucionales. No se genera el logotipo que no aparece en el texto.\n- Se relacionan CSM y SC-CIX sin declarar aprobado un reglamento futuro. CE-CIII mantiene su carácter de anteproyecto general; la corrección puntual CE-CII se incorpora por separado.\n\n' if es else '## Resultado da integração\n\n- Incorporada a nova redação do caput de Atas art. 3 aprovada na CE-CII. Preservados §§ 1–3, com anotação sobre modelos históricos que ainda mencionam folhas numeradas. O art. 20 não é substituído.\n- Dezesseis decisões de nomeações/indicações registradas com listas completas; arquivo FEP separado de uma eleição. Não se inserem nomes pessoais nos artigos gerais do Manual.\n- Identidade visual UCP e Projeto Alagoas registrados como políticas específicas, sem convertê-los em reformas constitucionais. Não se gera logomarca ausente do texto.\n- Relaciona-se CSM e SC-CIX sem declarar aprovado regimento futuro. CE-CIII conserva caráter de anteprojeto geral; a correção pontual CE-CII é incorporada separadamente.\n\n')
  text+=('| Decisión | Tipo de efecto | Destino |\n| --- | --- | --- |\n' if es else '| Decisão | Tipo de efeito | Destino |\n| --- | --- | --- |\n')
  types={'appointment':('Nombramiento o nominación','Nomeação ou indicação'),'institutional-policy':('Identidad visual','Identidade visual'),'program-specific-policy':('Política de proyecto','Política de projeto'),'administrative-archive':('Archivo de nominaciones','Arquivo de indicações'),'replace-caput':('Modificación del encabezamiento','Alteração do caput')}
  for e in selected:text+=f"| {e['source']} | {types[e['kind']][0 if es else 1]} | {', '.join(e['targets']) or ('Digesto y apuntes' if es else 'Digesto e apontamentos')} |\n"
  for e in selected:
   r=by[e['source']];text+=f"\n## {e['source']}\n\nPDF: {', '.join(map(str,e['pages']))}.\n\n{e['noteEs' if es else 'notePt']}\n\n{e['limitsEs' if es else 'limitsPt']}\n\n"
   text+=('### Evidencia — portugués\n\n' if es else '### Evidência — português\n\n')+e['evidencePt']+'\n\n'
   text+=('### Decisión completa — español cotejado\n\n' if es else '### Decisão completa — português original\n\n')+r['textEs' if es else 'textOriginal']+'\n\n'
   if e['kind']=='replace-caput':
    target=by['ATAS-art-3'];text+=('### Actas art. 3 — texto histórico 2025\n\n' if es else '### Atas art. 3 — texto histórico 2025\n\n')+target['textEs' if es else 'textOriginal']+'\n\n'
    text+=('### Actas art. 3 — redacción integrada parcial\n\n' if es else '### Atas art. 3 — redação integrada parcial\n\n')+target['integratedTextEs' if es else 'integratedTextPt']+'\n\n'
  text+=('Siguiente examen: desde SC-2026-CCXXI, excluyendo decisiones ya examinadas. Revisión de reglamentos con transición pendiente.\n' if es else 'Próximo exame: desde SC-2026-CCXXI, excluindo decisões já examinadas. Revisão de regimentos com transição pendente.\n')
  path.write_text(text)
 render_later_batches(c,effects)

