 types.update({'mission-support-continuation': ('Continuidad de sustento misionero', 'Continuidade de sustento missionário'), 'candidate-transfer-interpretation': ('Transferencia conciliar de candidato/licenciado', 'Transferência conciliar de candidato/licenciado'), 'society-congress-commission-interpretation': ('Comisiones previas de Congreso SAF', 'Comissões prévias de Congresso SAF'), 'procedural-defect-returned': ('Trámite irregular sin mérito', 'Tramitação irregular sem mérito'), 'society-minute-books-interpretation': ('Libros de actas separados SAF', 'Livros de atas separados SAF'), 'hymnal-revision-referral': ('Revisión de himnario remitida', 'Revisão de hinário remetida'), 'doctrinal-proposal-referral': ('Propuesta doctrinal remitida', 'Proposta doutrinária remetida'), 'disciplined-minister-support-clarification': ('Sustento de ministro disciplinado', 'Sustento de ministro disciplinado'), 'presbytery-registry-update': ('Registro presbiterial', 'Registro presbiterial')})
 types.update({'presbytery-merger-registry': ('Fusión y baja presbiterial', 'Fusão e exclusão presbiterial'), 'synod-creation-and-commission': ('Creación sinodal y comisión especial', 'Criação sinodal e comissão especial'), 'financial-examination-prejudiced': ('Examen contable sin mérito por competencia', 'Exame contábil sem mérito por competência'), 'institution-statute-ratified': ('Alteraciones estatutarias referendadas', 'Alterações estatutárias referendadas'), 'specific-property-contract-ratified': ('Alteración contractual referendada', 'Alteração contratual referendada'), 'institution-statute-approved-with-procedure': ('Estatuto específico aprobado y trámite', 'Estatuto específico aprovado e tramitação'), 'synod-statute-rules-approved-with-corrections': ('Estatuto/reglamento sinodal con correcciones', 'Estatuto/regimento sinodal com correções'), 'synod-statute-rules-approved': ('Estatuto/reglamento sinodal aprobado', 'Estatuto/regimento sinodal aprovado'), 'financial-examination-report-approved': ('Informe de examen contable aprobado', 'Relatório de exame contábil aprovado'), 'financial-report-approved-with-budget-observation': ('Informe aprobado con observación presupuestaria', 'Relatório aprovado com observação orçamentária')})
 types.update({'financial-report-approved-with-controls': ('Informe contable aprobado y controles', 'Relatório contábil aprovado e controles'), 'seminary-reports-approved-with-pending-examination': ('Informes aprobados y examen pendiente', 'Relatórios aprovados e exame pendente'), 'administrative-acts-partially-annulled': ('Actos administrativos parcialmente anulados', 'Atos administrativos parcialmente anulados'), 'merits-stayed-for-evidence': ('Mérito suspendido por instrucción', 'Mérito sobrestado por instrução'), 'educational-proposal-referral': ('Propuesta educacional remitida', 'Proposta educacional remetida'), 'liturgical-letter-publication': ('Publicación de carta litúrgica existente', 'Publicação de carta litúrgica existente'), 'juret-indications-referred-with-realignment': ('Indicaciones remitidas y ajuste Recife', 'Indicações remetidas e ajuste Recife'), 'individual-retirement-without-ipb-charge': ('Jubilación individual sin carga IPB', 'Jubilação individual sem ônus IPB')})
 types.update({'sentence-reform-status-registered': ('Sentencia reformada registrada', 'Sentença reformada registrada'), 'ministerial-restoration-registered': ('Restauración ministerial registrada', 'Restauração ministerial registrada'), 'ministerial-register-ci48c': ('Baja ministerial bajo CI48 c', 'Baixa ministerial sob CI48 c'), 'ministerial-register-ci48b': ('Baja ministerial bajo CI48 b', 'Baixa ministerial sob CI48 b'), 'ministerial-register-ci48a': ('Baja ministerial bajo CI48 a', 'Baixa ministerial sob CI48 a')})
 for config in sorted(d.glob('integracion_lote_*.json')):
  number=config.stem.rsplit('_',1)[-1]
  if int(number)<3:continue
  batch=json.loads(config.read_text());selected=[by_source[rid] for rid in batch['ids']]
  for lang in ['es','pt']:
   es=lang=='es';path=d/f'integracion_normativa_lote_{number}_2026_{lang}.md'
   if path.exists():continue
   text=(f'# Integración normativa 2026 — lote {number}\n\n> Edición de trabajo no oficial. {len(selected)} decisiones completas examinadas por sus efectos. Avance al cierre del lote: {batch["reviewedDecisionsAfterBatch"]}/398 examinadas; {batch["pendingDecisionsAfterBatch"]} pendientes. Digesto traducido y cotejado: 398/398. Sin certificación externa; consolidación y revisión editorial final pendientes.\n\n' if es else f'# Integração normativa 2026 — lote {number}\n\n> Edição de trabalho não oficial. {len(selected)} decisões integrais examinadas quanto aos efeitos. Avanço ao final do lote: {batch["reviewedDecisionsAfterBatch"]}/398 examinadas; {batch["pendingDecisionsAfterBatch"]} pendentes. Digesto traduzido e conferido: 398/398. Sem certificação externa; consolidação e revisão editorial final pendentes.\n\n')
   text+=batch['summaryEs' if es else 'summaryPt']
   text+=('| Decisión | Efecto | Remisiones |\n| --- | --- | --- |\n' if es else '| Decisão | Efeito | Remissões |\n| --- | --- | --- |\n')
   for e in selected:text+=f"| {e['source']} | {types[e['kind']][0 if es else 1]} | {', '.join(e['targets']) or ('Digesto y apuntes' if es else 'Digesto e apontamentos')} |\n"
   for e in selected:
    r=by[e['source']];text+=f"\n## {e['source']}\n\nPDF: {', '.join(map(str,e['pages']))}.\n\n{e['noteEs' if es else 'notePt']}\n\n{e['limitsEs' if es else 'limitsPt']}\n\n"
    text+=('### Evidencia — portugués\n\n' if es else '### Evidência — português\n\n')+e['evidencePt']+'\n\n'
    if e.get('regulatoryAdjustments'):
     text+=('### Ajustes aprobados a–cc\n\n' if es else '### Ajustes aprovados a–cc\n\n')
     for adjustment in e['regulatoryAdjustments']:text+='#### '+adjustment['marker']+'\n\n'+adjustment['textEs' if es else 'textPt']+'\n\n'
    text+=('### Decisión completa — español cotejado\n\n' if es else '### Decisão completa — português original\n\n')+r['textEs' if es else 'textOriginal']+'\n\n'
   if batch['nextId'] is not None:text+=('Siguiente examen: ' if es else 'Próximo exame: ')+batch['nextId']+'.\n'
   else:text+=('Examen documental de efectos concluido: 398/398. Siguiente fase: consolidación y revisión editorial final.\n' if es else 'Exame documental de efeitos concluído: 398/398. Próxima fase: consolidação e revisão editorial final.\n')
   path.write_text(text)
